#include<iostream>
 #include<cmath>
 using namespace std;

 class ToaDo{
 	private:
 		float hoanh;
 		float tung;
 	public:
 		void nhap(){
 			cout<<"Nhap tung do va hoanh do:";
 			cin>>hoanh>>tung;
		 }
		 void xuat(){
		 	cout<<endl<<"("<<hoanh<<","<<tung<<")";
		 }
		 float KhoangCach(){
		 	return sqrt(hoanh*hoanh+tung*tung);
		 }
 };
 class DiemMau : public ToaDo{
 	private:
 		int mau;
 	public:
 		void nhap(){
 			ToaDo::nhap();
 			cout<<"Nhap mau:";
 			cin>>mau;
		 }
		 void xuat(){
		 	ToaDo::xuat();
		 	cout<<" "<<mau;
		 }
		 int getMau(){
		 	return mau;
		 }
 };
int main(){
 	int n;
 	cout<<"Nhap n:";
 	cin>>n;
 	DiemMau a[100];
 	for(int i=0;i<n;i++){
 		a[i].nhap();
	}
	int mauDo=0, mauVang=0, mauXanh=0;
	for(int i=0;i<n;i++){
	 	if(a[i].getMau()==1){
	 		mauDo++;
		}
		else if(a[i].getMau()==2){
		 	mauVang++;
		}
		else if(a[i].getMau()==3){
		 	mauXanh++;
		}
	}
	cout<<"\n Thong ke";
	cout<<"So diem mau Do:"<<mauDo<<endl;
	cout<<"So diem mau Vang:"<<mauVang<<endl;
	cout<<"So diem mau Xanh:"<<mauXanh<<endl;
	int t=0;
	for(int i=1;i<n;i++){
		if(a[i].KhoangCach()>a[t].KhoangCach()){
			t=i;
		}
	}
	cout<<"Cac diem co khoang cach lon nhat:"<<endl;
	a[t].xuat();
	return 0;
}

